import pdfplumber, re
path='/app/data/handbook.pdf'
with pdfplumber.open(path) as pdf:
    for i, page in enumerate(pdf.pages, start=1):
        text = page.extract_text() or ''
        if re.search(r'preheat|TAL|liquidus|peak|conveyor|speed|dwell', text, flags=re.I):
            print('\n--- page', i, '---')
            # print some lines around keywords
            lines = text.splitlines()
            for line in lines:
                if re.search(r'preheat|TAL|liquidus|peak|conveyor|speed|dwell', line, flags=re.I):
                    print(line)
